"""An in-memory note store: add, list, delete. Notes are (id, text) pairs."""


class NoteStore:
    def __init__(self):
        self._notes = {}
        self._next = 1

    def add(self, text: str) -> int:
        note_id = self._next
        self._notes[note_id] = text
        self._next += 1
        return note_id

    def list(self) -> list[tuple[int, str]]:
        return sorted(self._notes.items())

    def delete(self, note_id: int) -> bool:
        return self._notes.pop(note_id, None) is not None

